/**
 * The complying development prerequisites of the Codes SEPP, and which of them we test.
 *
 * GENERATED by scratchpad/gen_cdc.py - do not hand-edit. Two sources: the clause numbers and the
 * verbatim requirement text come from sheet 1 of the Department workbook "CDC Rules - Part 3, 9 & HSEPP";
 * what we actually test comes from the notebook "07 - CDC rules". The join between them is a hand-written
 * map in the generator, because matching a column name to a clause by text would guess, and a wrong
 * citation on a page about citations is worse than none.
 *
 * NOT VERIFIED AGAINST THE INSTRUMENT: legislation.nsw.gov.au refuses automated requests, so this is the
 * Department's compilation rather than a reading of epi-2008-0572 itself. Every clause links out.
 */

/** One link out of the workbook's Data Source column. */
export interface DataSource {
  url: string
  /** The dataset's own name, from the end of the URL. */
  label: string
  /** Who publishes it. */
  host: string
}

export interface SeppRequirement {
  /** As the instrument numbers it, e.g. "1.19(1)(c)". */
  clause: string
  /** The words of the requirement, from the workbook. */
  text: string
  /** Where the workbook says the answer comes from, verbatim. */
  dataSource: string | null
  /** The same cell split into links. */
  sources: DataSource[]
  /** Whatever that cell said besides the links. */
  sourceNote: string | null
  note: string | null
  /** Our columns that test it, empty when we do not. */
  columns: string[]
  tested: boolean
  /** True when this clause only introduces the ones beneath it; its state is theirs. */
  isParent: boolean
  services: (string | null)[]
  /** Set where our test is narrower or wider than the clause. */
  divergence: string | null
}

/** A check we run that the workbook's prerequisites do not account for. */
export interface UnmappedCheck {
  column: string
  land: string
  service: string | null
}

/** One of our per-type tests, in the units a reader thinks in. */
export interface TypeTest {
  /** The key of the rule in the notebook. */
  key: string
  name: string
  checks: { column: string; says: string }[]
}

/** A requirement that belongs to one development type rather than to every certificate. */
export interface TypeRequirement {
  clause: string
  text: string
  /** Everything the sheet writes underneath the clause: the flood parts, the lists, the asides. */
  subItems: string[]
  dataSource: string | null
  sources: DataSource[]
  sourceNote: string | null
  note: string | null
  testedBy: { type: string; column: string; says: string }[]
  tested: boolean
  /** The clause in the instrument it belongs to, Codes SEPP or Housing SEPP. */
  href: string | null
}

export interface CdcType {
  key: string
  name: string
  /** The code within the instrument, e.g. "Low Rise Housing Diversity Code". */
  code: string
  /** The sheet of the workbook it was read from. */
  sheet: string
  /** True when the sheet says the type also has to clear the general prerequisites. */
  inheritsGeneral: boolean
  note: string | null
  tests: TypeTest[]
  requirements: TypeRequirement[]
  testedCount: number
}

